SELECT u.id, u.username, u.email, u.avatar, u.bio, u.github, u.bilibili, u.role, u.status, (SELECT COUNT(*) FROM articles WHERE create_by = u.id AND deleted = 0) AS article_count, (SELECT COUNT(*) FROM comments WHERE user_id = u.id AND deleted = 0) AS comment_count, u.create_time, u.update_time FROM users u WHERE u.deleted = 0
AND u.role = #{role}
AND u.status = #{status}
AND (u.username ILIKE CONCAT('%', #{keyword}, '%') OR u.email ILIKE CONCAT('%', #{keyword}, '%'))
AND u.create_time >= #{startTime}
AND u.create_time <= #{endTime}
ORDER BY u.create_time DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM users u
WHERE u.deleted = 0

    AND u.role = #{role}


    AND u.status = #{status}


    AND (u.username ILIKE CONCAT('%', #{keyword}, '%')
         OR u.email ILIKE CONCAT('%', #{keyword}, '%'))


    AND u.create_time >= #{startTime}


    AND u.create_time <= #{endTime}
